import{_ as t,o as a,c as o,a5 as n}from"./chunks/framework.DJo0M80U.js";const d=JSON.parse('{"title":"借用构造函数","description":"借用构造函数(constructor stealing)的技术（有时也叫做伪造对象或经典继承）。 基本思路： 在子类型构造函数的内部调用父类的构造函数。通过使用apply()和call()方法绑定超类构造函数的执行环境为子类。相当于创建子类时，把创建父类实例的代码执行了一次，不过。","frontmatter":{"title":"借用构造函数","date":"2026-08-11T00:00:00.000Z","categories":["JavaScript 系统教程"],"tags":["JavaScript","前端","教程","OneNote","对象、数组与函数"],"description":"借用构造函数(constructor stealing)的技术（有时也叫做伪造对象或经典继承）。 基本思路： 在子类型构造函数的内部调用父类的构造函数。通过使用apply()和call()方法绑定超类构造函数的执行环境为子类。相当于创建子类时，把创建父类实例的代码执行了一次，不过。","sidebarWeight":148,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/b-原生js/面向对象程序设计/(80m)继承/(10m)借用构造函数.md"},"headers":[],"relativePath":"posts/JavaScript系统教程/03-对象、数组与函数/(80m)继承/(10m)借用构造函数.md","filePath":"posts/JavaScript系统教程/03-对象、数组与函数/(80m)继承/(10m)借用构造函数.md"}'),s={name:"posts/JavaScript系统教程/03-对象、数组与函数/(80m)继承/(10m)借用构造函数.md"};function r(c,e,l,p,i,u){return a(),o("div",null,[...e[0]||(e[0]=[n('<div><h1 id="借用构造函数" tabindex="-1">借用构造函数 <a class="header-anchor" href="#借用构造函数" aria-label="Permalink to &quot;借用构造函数&quot;">​</a></h1><blockquote><p>本节目标：理解“借用构造函数”的核心思路，并能把它用于实际开发或面试表达。 借用构造函数(constructor stealing)的技术（有时也叫做伪造对象或经典继承）。</p></blockquote><p>**基本思路：**在子类型构造函数的内部调用父类的构造函数。通过使用apply()和call()方法绑定超类构造函数的执行环境为子类。相当于创建子类时，把创建父类实例的代码执行了一次，不过this指向的是子类实例，如下： function SuperType() { this.colors = [&#39;red&#39;, &#39;blue&#39;, &#39;green&#39;]; } function SubType() { //继承了SuperType SurperType.call(this); } var instance1 = new SubType() instance1.colors.push(&#39;black&#39;); console.log(instance1.colors);//&#39;red,blue,green,black&#39; var instance2 = new SubType(); console.log(instance2.colors);//&#39;red,blue,green&#39;</p><p><strong>可传递参数来让子类实例拥有了父类实例一样的非共享属性</strong> 相对原型链而言，借用构造函数还可以在子类型构造函数中向超类型构造函数传递参数。 如下例： function SuperType(name) { this.name = name; } function SubType() { //继承了SuperType，同时还传递了参数 SurperType.call(this, &#39;Nicholas&#39;); //实例属性 this.age = 29; } var instance1 = new SubType() console.log(instance.name);//&#39;Nicholas&#39; console.log(instance.age);//29</p><p><strong>注意点：</strong> 为了确保SuperType构造函数不会重写子类型的属性，可以在调用超类型构造函数后，再添加应该在子类型中定义的属性。</p><p><strong>单独借用构造函数的问题</strong></p><ul><li>子类实例的方法都在构造函数中定义，重复定义了可共用的方法或者说没有定义子类实例共用的方法。</li><li>没有继承到父类原型中定义的方法。</li></ul></div>',1)])])}const m=t(s,[["render",r]]);export{d as __pageData,m as default};
